g:.8px;color:#96aaa2;margin-bottom:6px}.mini-label span{float:right;color:#9ce7cb}.mini-label span:before{content:'';display:inline-block;width:5px;height:5px;background:#9ce7cb;border-radius:50%;margin-right:4px}#minimap{width:136px;height:104px;display:block}.toast{position:absolute;z-index:5;left:50%;top:24%;transform:translate(-50%,-10px);opacity:0;transition:.25s;pointer-events:none;background:rgba(8,19,24,.9);border:1px solid rgba(156,231,203,.48);padding:10px 18px;font:11px 'DM Mono',monospace;letter-spacing:1px;color:#baf3d9;text-align:center;max-width:90vw}.toast.show{opacity:1;transform:translate(-50%,0)}#crosshair{z-index:4;position:absolute;left:50%;top:50%;width:18px;height:18px;transform:translate(-50%,-50%);pointer-events:none;transition:transform .08s}#crosshair i{position:absolute;background:rgba(230,250,240,.86);box-shadow:0 0 3px #14211d}#crosshair i:nth-child(1){width:2px;height:5px;left:8px;top:0}#crosshair i:nth-child(2){width:2px;height:5px;left:8px;bottom:0}#crosshair i:nth-child(3){width:5px;height:2px;top:8px;left:0}#crosshair i:nth-child(4){width:5px;height:2px;top:8px;right:0}#crosshair b{position:absolute;width:2px;height:2px;border-radius:50%;background:#fff;left:8px;top:8px}.interaction{position:absolute;z-index:4;left:50%;top:59%;transform:translate(-50%,0);display:none;align-items:center;gap:9px;padding:7px 11px;background:rgba(8,18,22,.86);border:1px solid rgba(156,231,203,.28);font:9px 'DM Mono',monospace;letter-spacing:1px;color:#c7e0d6;white-space:nowrap}.interaction.visible{display:flex}.keycap{background:#a4e8cc;color:#10201c;font-weight:500;padding:4px 7px;font-size:10px}.screen,.modal{position:absolute;z-index:10;inset:0;display:grid;place-items:center;background:rgba(4,12,16,.64);backdrop-filter:blur(4px)}.screen.hidden,.modal.hidden{display:none}.screen-card{width:min(540px,calc(100vw - 32px));background:linear-gradient(140deg,rgba(13,28,32,.97),rgba(7,16,20,.97));border:1px solid rgba(166,221,207,.24);padding:38px 42px;box