(() => {
'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),mini=document.querySelector('#minimap'),mctx=mini.getContext('2d'),$=id=>document.getElementById(id);
const mapRows=['#################','#.....#.........#','#.....#.........#','#...............#','#.....#.........#','#.....###.###...#','#...............#','#...###...###...#','#...#.........#.#','#...#.........#.#','#...............#','#...............#','#################'];
const MW=mapRows[0].length,MH=mapRows.length,walls=mapRows.map(r=>r.split('').map(c=>c==='#'));
const taskDefs=[{x:3.5,y:5.5,name:'Power diversion',color:'#8de6bd',icon:'⌁'},{x:8.5,y:3.5,name:'Communications',color:'#7ad7ed',icon:'⌗'},{x:13.5,y:6.5,name:'Crew manifest',color:'#f2bd6d',icon:'▤'}], bombPos={x:14.5,y:10.35};
let W,H,dpr,keys={},held={},running=false,ended=false,locked=false,elapsed=0,timeLeft=105,toastTimer=0,fireCooldown=0,enemyAttack=0,pathTimer=0,player,enemy,tasks,bomb,ammo,totalAmmo,taskSequence=[],taskInput=[],taskOpen=false,nearest=null,soundOn=true,audioCtx=null,last=0;
const FOV=Math.PI*.39,TAU=Math.PI*2,norm=a=>{while(a>Math.PI)a-=TAU;while(a< -Math.PI)a+=TAU;return a},dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
function resize(){dpr=Math.min(devicePixelRatio||1,1.7);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
const wallAt=(x,y)=>x<0||y<0||x>=MW||y>=MH||walls[Math.floor(y)]?.[Math.floor(x)];
function freshGame(){player={x:2.55,y:2.55,a:.12,hp:100};enemy={x:13.45,y:2.5,hp:100,alive:true,visible:false,shotAt:0};tasks=taskDefs.map(t=>({...t,done:false}));bomb={...bombPos};ammo=12;totalAmmo=48;elapsed=0;timeLeft=105;running=true;ended=false;taskOpen=false;taskInput=[];enemyAttack=0;pathTimer=0;nearest=null;keys={};$('start-screen').classList.add('hidden');$('end-screen').classList.add('hidden');$('task-modal').classList.add('hidden');$('damage-vignette').style.boxShadow='inset 0 0 0 rgba(244,48,38,0)';$('ammo-current').textContent=ammo;$('ammo-total').textContent=totalAmmo;$('health-fill').style.width='100%';$('health-label').textContent='100';$('status-text').textContent='STABLE';updateObjective();toast('Find the three ship terminals. Keep moving.',2200);last=performance.now();requestAnimationFrame(loop);}
function showToast(text,duration=1700){const t=$('toast');t.textContent=text;t.classList.add('show');toastTimer=duration}function toast(text,duration){showToast(text,duration)}
function updateObjective(){let count=tasks.filter(t=>t.done).length;$('task-count').textContent=`EVIDENCE ${count} / 3`;$('task-progress').style.width=`${count/3*100}%`;if(count<3){$('objective-title').textContent='Find the impostor';$('objective-detail').textContent=`Complete ship tasks to gather evidence. ${count}/3 terminals secured.`}else if(enemy.alive){$('objective-title').textContent='Eliminate the impostor';$('objective-detail').textContent='Evidence confirms a hostile. Find and neutralize them.'}else{$('objective-title').textContent='Defuse the bomb';$('objective-detail').textContent='Reach the marked bomb site and hold E.'}}
function resizeText(){if(!running)return;}
function raycast(angle,max=20){let rx=Math.cos(angle),ry=Math.sin(angle),mx=Math.floor(player.x),my=Math.floor(player.y),ddx=Math.abs(1/(rx||1e-9)),ddy=Math.abs(1/(ry||1e-9)),sx,sy,sdx,sdy,side=0; if(rx<0){sx=-1;sdx=(player.x-mx)*ddx}else{sx=1;sdx=(mx+1-player.x)*ddx}if(ry<0){sy=-1;sdy=(player.y-my)*ddy}else{sy=1;sdy=(my+1-player.y)*ddy}let d=0;while(d<max){if(sdx<sdy){d=sdx;sdx+=ddx;mx+=sx;side=0}else{d=sdy;sdy+=ddy;my+=sy;side=1}if(mx<0||my<0||mx>=MW||my>=MH||walls[my][mx]){let hit=side===0?player.y+d*ry:player.x+d*rx;return{d,side,hit:hit-Math.floor(hit),mx,my}}}return{d:max,side:0,hit:0,mx,my}}
function clearShot(a,b){let angle=Math.atan2(b.y-a.y,b.x-a.x),d=dist(a,b);return raycast(angle,d+.05).d>=d-.13}
function drawWorld(){const horizon=H*.49;let sky=ctx.createLinearGradient(0,0,0,horizon);sky.addColorStop(0,'#18282a');sky.addColorStop(1,'#324443');ctx.fillStyle=sky;ctx.fillRect(0,0,W,horizon);let floor=ctx.createLinearGradient(0,horizon,0,H);floor.addColorStop(0,'#555b50');floor.addColorStop(.38,'#343c35');floor.addColorStop(1,'#101a1a');ctx.fillStyle=floor;ctx.fillRect(0,horizon,W,H-horizon);
