import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({headless:true, args:['--no-sandbox']});
const page = await browser.newPage({viewport:{width:1440,height:900}});
page.on('pageerror', e => console.error('PAGEERROR', e.message));
page.on('console', m => { if(m.type()==='error') console.error('CONSOLE',m.text()); });
await page.goto('http://localhost:3002');
await page.locator('#start-button').click();
const status=()=>page.evaluate(()=>({health:document.querySelector('#health-label').textContent, interaction:document.querySelector('#interaction').className, label:document.querySelector('#interaction-label').textContent, objective:document.querySelector('#objective-title').textContent,ammo:document.querySelector('#ammo-current').textContent,modal:document.querySelector('#task-modal').className}));
console.log('start', await status());
// release mouse lock for deterministic arrow-key turning
await page.evaluate(()=>document.exitPointerLock());
await page.keyboard.down('ArrowRight'); await page.waitForTimeout(800); await page.keyboard.up('ArrowRight');
await page.keyboard.down('w'); await page.waitForTimeout(1100); await page.keyboard.up('w');
console.log('at first terminal approach', await status());
await page.screenshot({path:'/tmp/opencode/game-check.png'});
await browser.close();

import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({headless:true,args:['--no-sandbox']});
const page = await browser.newPage({viewport:{width:1440,height:900}});
const errors=[];
page.on('pageerror',e=>errors.push(e.message));
page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
page.on('response',r=>{if(r.status()>=400)errors.push(`${r.status()} ${r.url()}`)});
await page.goto('http://localhost:3002');
const check=(condition,message)=>{if(!condition)throw Error(message);console.log('PASS',message)};
await page.locator('#start-button').click();
await page.evaluate(()=>document.exitPointerLock());
await page.keyboard.down('ArrowRight');await page.waitForTimeout(800);await page.keyboard.up('ArrowRight');
await page.keyboard.down('w');await page.waitForTimeout(1100);await page.keyboard.up('w');
check(await page.locator('#interaction-label').textContent()==='ACCESS POWER DIVERSION','player can reach first terminal');
await page.keyboard.press('e');
check(await page.locator('#task-modal').isVisible(),'terminal opens sequence puzzle');
const shapeToPulse={'●':1,'◆':2,'▲':3,'■':4};
for(let i=0;i<3;i++){
  const symbol=await page.locator(`#seq-${i}`).textContent();
  await page.getByRole('button',{name:`Pulse ${shapeToPulse[symbol]}`}).click();
}
await page.waitForTimeout(350);
check(await page.locator('#task-modal').isHidden(),'correct pulse sequence closes task');
check((await page.locator('#task-count').textContent()).includes('1 / 3'),'evidence count updates after task');
await page.mouse.click(700,500);
check(await page.locator('#ammo-current').textContent()==='11','click fires one round');
await page.keyboard.press('r');await page.waitForTimeout(850);
check(await page.locator('#ammo-current').textContent()==='12'&&await page.locator('#ammo-total').textContent()==='47','reload replenishes magazine and reserve');
await page.setViewportSize({width:390,height:844});
await page.waitForTimeout(150);
const mobile=await page.evaluate(()=>({controls:getComputedStyle(document.querySelector('#mobile-controls')).display,fire:document.querySelector('#mobile-fire').getBoundingClientRect().toJSON(),game:document.querySelector('#game').getBoundingClientRect().toJSON(),bodyWidth:document.body.scrollWidth,viewport:innerWidth}));
check(mobile.controls==='flex','mobile action controls display at phone width');
check(mobile.bodyWidth<=mobile.viewport,'mobile layout has no horizontal overflow');
await page.screenshot({path:'/tmp/opencode/game-mobile.png'});
check(errors.length===0,`no console/page/network errors (${errors.join('; ')})`);
console.log('MOBILE',mobile);
console.log('PASS complete browser checks');
await browser.close();

import { createRequire } from 'node:module';
const require=createRequire('/home/runner/.local/share/omgithub-playwright/package.json');const {chromium}=require('playwright');
const browser=await chromium.launch({headless:true,args:['--no-sandbox']});const page=await browser.newPage({viewport:{width:1440,height:900}});page.on('pageerror',e=>console.error('PAGEERROR',e.message));
await page.goto('http://localhost:3002');await page.locator('#start-button').click();await page.evaluate(()=>document.exitPointerLock());
