await waitKey('w',1870);await waitKey('ArrowRight',870);await waitKey('w',1130);console.log('near task3',await page.locator('#interaction-label').textContent(),await page.locator('#health-label').textContent());
if(await page.locator('#interaction-label').textContent()==='ACCESS CREW MANIFEST'){await solve();console.log('task3',await page.locator('#task-count').textContent(),await page.locator('#objective-title').textContent())}
await page.screenshot({path:'/tmp/opencode/game-route.png'});await browser.close();

