import { createRequire } from 'node:module';
const require=createRequire('/home/runner/.local/share/omgithub-playwright/node_modules/playwright/package.json');
const {chromium}=require('playwright');
const browser=await chromium.launch({headless:true,args:['--no-sandbox']});
const page=await browser.newPage({viewport:{width:390,height:844},deviceScaleFactor:1,isMobile:true,hasTouch:true});
const errors=[];page.on('pageerror',e=>errors.push(`PAGE ${e.message}`));page.on('console',m=>{if(m.type()==='error')errors.push(`CONSOLE ${m.text()}`)});
let source=await (await fetch('http://localhost:3002/game.js')).text();
const anchor='player={x:2.55,y:2.55,a:.12,hp:100};enemy={x:13.45,y:2.5,hp:100,alive:true};';
if(!source.includes(anchor))throw Error('Could not instrument initial state');
source=source.replace(anchor,'window.__touchState=()=>({player:{...player},ammo,totalAmmo,taskOpen,enemy:{...enemy}});'+anchor);
await page.route('**/game.js',r=>r.fulfill({status:200,contentType:'application/javascript',body:source}));
await page.goto('http://localhost:3002');
await page.locator('#start-button').tap();
const mobileVisible=await page.locator('#mobile-controls').evaluate(el=>getComputedStyle(el).display!=='none');
const state=()=>page.evaluate(()=>window.__touchState());
const move=page.locator('[data-move="forward"]');const box=await move.boundingBox();
const cdp=await page.context().newCDPSession(page);await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x:box.x+box.width/2,y:box.y+box.height/2,id:1}]});await page.waitForTimeout(500);await cdp.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});
const afterMove=await state();
const ammoBefore=(await state()).ammo;await page.locator('#mobile-fire').tap();const ammoAfter=(await state()).ammo;
// Place the player beside the first terminal to verify touch USE opens its puzzle.
await page.evaluate(()=>{player.x=3.5;player.y=5.5});await page.waitForTimeout(50);await page.locator('#mobile-interact').tap();await page.waitForTimeout(70);
const taskOpened=await page.locator('#task-modal').evaluate(el=>!el.classList.contains('hidden'));
await page.reload();
const favicon=await page.locator('link[rel="icon"]').getAttribute('href');
console.log(JSON.stringify({mobileVisible,afterMove,ammoBefore,ammoAfter,taskOpened,faviconDataUri:favicon?.startsWith('data:image/svg+xml,'),faviconLength:favicon?.length,errors},null,2));
await browser.close();
if(!mobileVisible||afterMove.player.y>=2.55||ammoAfter!==ammoBefore-1||!taskOpened||!favicon?.startsWith('data:image/svg+xml,')||errors.length)process.exitCode=1;

